void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 s = vec2(textureSize(iChannel0, 0));
    float t = iTime * 0.2;
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.x;

    uv /= 0.5 - uv.y;
    uv.y -= t;
    uv *= 2.0 / s;

    vec3 col;

    float m = 1.0;

    for (int i = 0; i < 8; i++) {
        vec2 p = uv;

        p *= s;
        p -= 0.5;

        p = floor(p) + smoothstep(vec2(0.4375, 0.0), vec2(0.5625, 1.0), fract(p));
        p.y += t;

        p += 0.5;
        p /= s;

        vec4 tex = texture(iChannel0, p);
        col += (tex.xyz * 2.0 - 1.0) * m;

        m *= 0.5;
        uv *= vec2(2.0, 1.125);
    }

    col = normalize(col) * 0.5 + 0.5;
    col *= pow(col.x, 3.0);
    col = mix(vec3(0.1, 0.1, 0.0), vec3(0.9, 0.9, 0.7), col);

    fragColor = vec4(col, 1.0);
}
